import { Component, inject, signal } from '@angular/core';
import { MoneyPipe } from '../currencies/money.pipe';
import { DashboardService, DashboardSummary } from './dashboard.service';
import { AgingReportPanel } from './aging-report';
import { CashFlowForecast } from './cash-flow-forecast';
import { RevenueReport } from './revenue-report';
import { TaxReport } from './tax-report';
import { TaxSummaryReport } from './tax-summary';
import { UpcomingRecurringInvoices } from './upcoming-recurring-invoices';

// Dashboard page: how many clients and projects there are (and how many clients were taken on this month), what was billed this month in the home currency,, and the total still owed in each currency
// (what is left to pay on invoices that have been sent but not yet fully paid; drafts are not
// counted), plus one grand total of it in the home currency with each invoice converted at the
// exchange rate from its own issue date (leaving out disputed and written-off invoices), and how many of those sent
// invoices (not disputed — a disputed invoice is kept out of the overdue chase) are past their due date, with what is overdue on them (left to pay plus accrued late fees and
// instalment interest, in the home currency), also split by how many days overdue each invoice is. Also lists the top five clients ranked by what they still owe
// converted into the home currency, each shown in their own currency and in the home currency (and again as a summary tile built from that same list, so the two never disagree), and the recurring invoices coming up with when each falls, and a forecast of the money expected in from scheduled instalments. Also shows how many tasks not yet done are past their due date, and the average number of days clients take to pay (issue date to final payment on paid invoices), and what share of everything billed has been collected. An aging report across all clients, a tax summary, a tax report by rate and a revenue report for a chosen date range can be opened from here.
@Component({
  selector: 'app-dashboard',
  imports: [MoneyPipe, AgingReportPanel, CashFlowForecast, RevenueReport, TaxReport, TaxSummaryReport, UpcomingRecurringInvoices],
  template: `
    <h1>Dashboard</h1>

    @if (loadError()) {
      <p role="alert" data-testid="dashboard-error">{{ loadError() }}</p>
    } @else if (summary(); as s) {
      <dl data-testid="dashboard-summary">
        <div>
          <dt>Clients</dt>
          <dd data-testid="dashboard-clients-count">{{ s.clients }}</dd>
        </div>
        <div>
          <dt>New clients this month</dt>
          <dd data-testid="dashboard-new-clients">{{ s.newClientsThisMonth }}</dd>
        </div>
        <div>
          <dt>Jobs</dt>
          <dd data-testid="dashboard-projects-count">{{ s.projects }}</dd>
        </div>
        <div>
          <dt>Outstanding</dt>
          @for (t of s.outstanding; track t.currency) {
            <dd [attr.data-testid]="'dashboard-outstanding-' + t.currency">{{ t.amount | money: t.currency }}</dd>
          } @empty {
            <dd data-testid="dashboard-outstanding-none">Nothing owed</dd>
          }
        </div>
        <div>
          <dt>Outstanding in {{ s.homeCurrency }} (converted at each invoice's date, excluding disputed and written-off)</dt>
          <dd data-testid="dashboard-outstanding-home"><span data-testid="kpi-outstanding">{{ s.outstandingHome | money: s.homeCurrency }}</span></dd>
        </div>
        <div>
          <dt>Billed this month (in {{ s.homeCurrency }})</dt>
          <dd data-testid="kpi-billings-month">{{ s.billingsThisMonth | money: s.homeCurrency }}</dd>
        </div>
        <div>
          <dt>Collection rate (collected of what was billed)</dt>
          @if (s.collectionRate !== null) {
            <dd data-testid="kpi-collection-rate">{{ s.collectionRate }}%</dd>
          } @else {
            <dd data-testid="kpi-collection-rate-none">Nothing billed yet</dd>
          }
        </div>
        <div>
          <dt>Overdue invoices</dt>
          <dd data-testid="dashboard-overdue-count">{{ s.overdue }}</dd>
        </div>
        <div>
          <dt>Overdue amount (including late fees and interest)</dt>
          <dd data-testid="dashboard-overdue-amount">{{ s.overdueAmount | money: s.homeCurrency }}</dd>
        </div>
        <div>
          <dt>Overdue up to 30 days</dt>
          <dd data-testid="dashboard-overdue-0-30">{{ s.overdueBuckets.days0To30 | money: s.homeCurrency }}</dd>
        </div>
        <div>
          <dt>Overdue 31 to 60 days</dt>
          <dd data-testid="dashboard-overdue-31-60">{{ s.overdueBuckets.days31To60 | money: s.homeCurrency }}</dd>
        </div>
        <div>
          <dt>Overdue more than 60 days</dt>
          <dd data-testid="dashboard-overdue-60-plus">{{ s.overdueBuckets.days60Plus | money: s.homeCurrency }}</dd>
        </div>
        <div>
          <dt>Open tasks</dt>
          <dd data-testid="dashboard-open-tasks">{{ s.openTasks }}</dd>
        </div>
        <div>
          <dt>Overdue tasks</dt>
          <dd data-testid="dashboard-overdue-tasks-count">{{ s.overdueTasks }}</dd>
        </div>
        <div>
          <dt>Average days to pay</dt>
          @if (s.averageDaysToPay !== null) {
            <dd data-testid="kpi-days-to-pay">{{ s.averageDaysToPay }}</dd>
          } @else {
            <dd data-testid="kpi-days-to-pay-none">No paid invoices yet</dd>
          }
        </div>
        <div data-testid="kpi-top-clients">
          <dt>Top clients owed (in {{ s.homeCurrency }})</dt>
          @for (c of s.topClients; track c.id) {
            <dd [attr.data-testid]="'kpi-top-client-row-' + c.id">
              <span data-testid="kpi-top-client-name">{{ c.name }}</span>:
              <span data-testid="kpi-top-client-amount">{{ c.outstandingHome | money: s.homeCurrency }}</span>
            </dd>
          } @empty {
            <dd data-testid="kpi-top-clients-none">No clients owe anything</dd>
          }
        </div>
      </dl>

      <section data-testid="dashboard-top-clients" aria-labelledby="dashboard-top-clients-heading">
        <h2 id="dashboard-top-clients-heading">Top clients by amount owed (in {{ s.homeCurrency }})</h2>
        @if (s.topClients.length) {
          <ol>
            @for (c of s.topClients; track c.id) {
              <li [attr.data-testid]="'top-client-row-' + c.id">
                <span data-testid="top-client-name">{{ c.name }}</span>:
                <span data-testid="top-client-amount">{{ c.outstanding | money: c.currency }}</span>
                @if (c.currency !== s.homeCurrency) {
                  (<span data-testid="top-client-amount-home">{{ c.outstandingHome | money: s.homeCurrency }}</span>)
                }
              </li>
            }
          </ol>
        } @else {
          <p data-testid="dashboard-top-clients-empty">No clients owe anything.</p>
        }
      </section>
    } @else {
      <p data-testid="dashboard-loading">Loading…</p>
    }

    <app-upcoming-recurring-invoices />

    <app-cash-flow-forecast />

    <button
      type="button"
      data-testid="aging-report-open"
      aria-controls="aging-report"
      [attr.aria-expanded]="agingReportOpen()"
      (click)="agingReportOpen.set(!agingReportOpen())"
    >
      {{ agingReportOpen() ? 'Hide aging report' : 'Aging report' }}
    </button>
    @if (agingReportOpen()) {
      <app-aging-report id="aging-report" />
    }

    <button
      type="button"
      data-testid="tax-summary-open"
      aria-controls="tax-summary"
      [attr.aria-expanded]="taxSummaryOpen()"
      (click)="taxSummaryOpen.set(!taxSummaryOpen())"
    >
      {{ taxSummaryOpen() ? 'Hide tax summary' : 'Tax summary' }}
    </button>
    @if (taxSummaryOpen()) {
      <app-tax-summary id="tax-summary" />
    }

    <button
      type="button"
      data-testid="tax-report-open"
      aria-controls="tax-report"
      [attr.aria-expanded]="taxReportOpen()"
      (click)="taxReportOpen.set(!taxReportOpen())"
    >
      {{ taxReportOpen() ? 'Hide tax report' : 'Tax report by rate' }}
    </button>
    @if (taxReportOpen()) {
      <app-tax-report id="tax-report" />
    }

    <button
      type="button"
      data-testid="revenue-report-open"
      aria-controls="revenue-report"
      [attr.aria-expanded]="revenueReportOpen()"
      (click)="revenueReportOpen.set(!revenueReportOpen())"
    >
      {{ revenueReportOpen() ? 'Hide revenue report' : 'Revenue report' }}
    </button>
    @if (revenueReportOpen()) {
      <app-revenue-report id="revenue-report" />
    }
  `,
})
export class Dashboard {
  protected readonly summary = signal<DashboardSummary | null>(null);
  protected readonly loadError = signal<string | null>(null);
  protected readonly agingReportOpen = signal(false);
  protected readonly taxSummaryOpen = signal(false);
  protected readonly taxReportOpen = signal(false);
  protected readonly revenueReportOpen = signal(false);

  constructor() {
    inject(DashboardService)
      .summary()
      .subscribe({
        next: (s) => this.summary.set(s),
        error: () => this.loadError.set('Could not load the dashboard. Please try again.'),
      });
  }
}
import { HttpClient, HttpParams } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { Observable } from 'rxjs';
import { CurrencyCode } from '../clients/client.service';

export interface TopClient {
  id: number;
  name: string;
  /** The client's currency; what they owe is in it. */
  currency: CurrencyCode;
  outstanding: number;
  /** What they owe converted into the home currency; the clients are ranked by it. */
  outstandingHome: number;
}

/** What is still owed in one currency; different currencies are never added together. */
export interface CurrencyTotal {
  currency: CurrencyCode;
  amount: number;
}

/** What is overdue, in the home currency, by how many days past due. */
export interface OverdueBuckets {
  days0To30: number;
  days31To60: number;
  days60Plus: number;
}

export interface DashboardSummary {
  clients: number;
  projects: number;
  /** What is still owed, one total per currency anything is owed in. */
  outstanding: CurrencyTotal[];
  /** Everything outstanding as one total in the home currency, each invoice converted at its issue date's rate; disputed and written-off invoices are left out. */
  outstandingHome: number;
  overdue: number;
  /** The currency the overdue amount is given in. */
  homeCurrency: CurrencyCode;
  /** What is left to pay on overdue invoices plus the late fees and instalment interest they have built up, in the home currency. */
  overdueAmount: number;
  /** The overdue amount split by how many days past due each invoice is. */
  overdueBuckets: OverdueBuckets;
  topClients: TopClient[];
  /** How many tasks are not yet done. */
  openTasks: number;
  /** How many tasks not yet done are past their due date. */
  overdueTasks: number;
  /** Average days from issue to final payment on paid invoices, rounded; null when no invoice has been paid. */
  averageDaysToPay: number | null;
  /** How many clients were taken on in the current month. */
  newClientsThisMonth: number;
  /** What was billed (invoices issued and sent, not drafts or cancelled) in the current month, in the home currency. */
  billingsThisMonth: number;
  /** What has been collected over what was billed (sent invoices), as a whole percentage in the home currency; null when nothing has been billed. */
  collectionRate: number | null;
}

/** The tax charged on invoices issued on or between two dates, in the home currency. */
export interface TaxSummary {
  from: string;
  to: string;
  homeCurrency: CurrencyCode;
  /** How many invoices the tax came from. */
  invoices: number;
  tax: number;
  /** The levy (second tax). */
  levy: number;
  /** The tax and levy together. */
  total: number;
}

/** The sales tax charged at one rate, in the home currency. */
export interface RateTax {
  /** The tax rate as a percentage. */
  rate: number;
  /** How many invoices were taxed at the rate. */
  invoices: number;
  /** What the tax at the rate was charged on. */
  taxableBase: number;
  tax: number;
}

/** The sales tax charged on invoices issued on or between two dates, in the home currency, broken down by rate. */
export interface TaxReport {
  from: string;
  to: string;
  homeCurrency: CurrencyCode;
  /** How many invoices the tax came from. */
  invoices: number;
  taxableBase: number;
  tax: number;
  /** The lowest rate first; only the rates something was taxed at. */
  rates: RateTax[];
}

/** The revenue billed for one job (project), in the home currency. */
export interface JobRevenue {
  projectId: number;
  projectName: string;
  clientName: string;
  /** How many invoices the job's revenue came from. */
  invoices: number;
  amount: number;
}

/** The revenue billed on invoices issued in one calendar month, in the home currency. */
export interface MonthRevenue {
  /** The month as yyyy-MM. */
  month: string;
  /** How many invoices the month's revenue came from. */
  invoices: number;
  amount: number;
}

/**
 * The revenue billed on invoices issued on or between two dates (over all time when the dates are null), in the
 * home currency, broken down by job with the highest-earning job first, and by month with the earliest first.
 */
export interface RevenueReport {
  from: string | null;
  to: string | null;
  homeCurrency: CurrencyCode;
  /** How many invoices the revenue came from. */
  invoices: number;
  total: number;
  jobs: JobRevenue[];
  /** Only the months something was billed in. */
  months: MonthRevenue[];
}

/** The revenue billed on invoices issued on or between two dates, in the home currency. */
export interface PeriodRevenue {
  from: string;
  to: string;
  /** How many invoices the revenue came from. */
  invoices: number;
  total: number;
}

/** The revenue of two periods side by side, with the change from the first to the second. */
export interface RevenueComparison {
  homeCurrency: CurrencyCode;
  a: PeriodRevenue;
  b: PeriodRevenue;
  change: number;
  /** The change as a whole percentage of the first period's revenue; null when nothing was billed in it. */
  changePercent: number | null;
}

/** One instalment expected in, in its invoice's currency. */
export interface ForecastEntry {
  id: number;
  date: string;
  amount: number;
  currency: CurrencyCode;
  invoiceId: number;
  projectId: number;
  projectName: string;
  clientName: string;
}

/** The money expected in from instalments still to be paid, earliest due first, with the total in the home currency. */
export interface Forecast {
  homeCurrency: CurrencyCode;
  entries: ForecastEntry[];
  total: number;
}

/**
 * How old the debt across all clients is as at a date, in the home currency: what is left to pay on sent invoices
 * split into current (not yet due, or up to 30 days overdue), 31 to 60 days and more than 60 days overdue.
 */
export interface AgingReport {
  asOf: string;
  homeCurrency: CurrencyCode;
  current: number;
  days30To60: number;
  days60Plus: number;
  total: number;
  invoices: AgingReportLine[];
}

/** The age bucket an invoice falls in on the aging report. */
export type AgingBucket = 'CURRENT' | 'DAYS_30_60' | 'DAYS_60_PLUS';

/** One invoice behind the aging report: what is left to pay on it in the home currency, and its bucket. */
export interface AgingReportLine {
  invoiceId: number;
  projectId: number;
  clientId: number;
  clientName: string;
  dueDate: string | null;
  daysOverdue: number;
  bucket: AgingBucket;
  amount: number;
}

@Injectable({ providedIn: 'root' })
export class DashboardService {
  private readonly http = inject(HttpClient);

  summary(): Observable<DashboardSummary> {
    return this.http.get<DashboardSummary>('/api/dashboard');
  }

  taxSummary(from: string, to: string): Observable<TaxSummary> {
    return this.http.get<TaxSummary>('/api/dashboard/tax-summary', { params: new HttpParams().set('from', from).set('to', to) });
  }

  taxReport(from: string, to: string): Observable<TaxReport> {
    return this.http.get<TaxReport>('/api/dashboard/tax-report', { params: new HttpParams().set('from', from).set('to', to) });
  }

  /** The revenue report over the given range, or over all time when no range is given. */
  revenueReport(range?: { from: string; to: string }): Observable<RevenueReport> {
    const params = range ? new HttpParams().set('from', range.from).set('to', range.to) : new HttpParams();
    return this.http.get<RevenueReport>('/api/dashboard/revenue-report', { params });
  }

  /** The revenue of two periods, A and B, side by side. */
  revenueComparison(a: { from: string; to: string }, b: { from: string; to: string }): Observable<RevenueComparison> {
    const params = new HttpParams().set('aFrom', a.from).set('aTo', a.to).set('bFrom', b.from).set('bTo', b.to);
    return this.http.get<RevenueComparison>('/api/dashboard/revenue-compare', { params });
  }

  agingReport(): Observable<AgingReport> {
    return this.http.get<AgingReport>('/api/dashboard/aging-report');
  }

  forecast(): Observable<Forecast> {
    return this.http.get<Forecast>('/api/dashboard/forecast');
  }
}
package net.officefloor.hq.app.dashboard;

import java.time.LocalDate;
import org.springframework.format.annotation.DateTimeFormat;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api/dashboard")
public class DashboardController {

    private final DashboardService service;

    public DashboardController(DashboardService service) {
        this.service = service;
    }

    @GetMapping
    public DashboardResponse summary() {
        return service.summary();
    }

    /** The tax charged on invoices issued on or between the given dates. */
    @GetMapping("/tax-summary")
    public TaxSummaryResponse taxSummary(@RequestParam @DateTimeFormat(iso = DateTimeFormat.ISO.DATE) LocalDate from,
            @RequestParam @DateTimeFormat(iso = DateTimeFormat.ISO.DATE) LocalDate to) {
        return service.taxSummary(from, to);
    }

    /** The sales tax charged on invoices issued on or between the given dates, broken down by tax rate. */
    @GetMapping("/tax-report")
    public TaxReportResponse taxReport(@RequestParam @DateTimeFormat(iso = DateTimeFormat.ISO.DATE) LocalDate from,
            @RequestParam @DateTimeFormat(iso = DateTimeFormat.ISO.DATE) LocalDate to) {
        return service.taxReport(from, to);
    }

    /**
     * The revenue billed on invoices issued on or between the given dates, broken down by job. Without both dates the
     * revenue is over all time.
     */
    @GetMapping("/revenue-report")
    public RevenueReportResponse revenueReport(
            @RequestParam(required = false) @DateTimeFormat(iso = DateTimeFormat.ISO.DATE) LocalDate from,
            @RequestParam(required = false) @DateTimeFormat(iso = DateTimeFormat.ISO.DATE) LocalDate to) {
        return service.revenueReport(from, to);
    }

    /** The revenue billed in two periods (each on or between its dates), side by side. */
    @GetMapping("/revenue-compare")
    public RevenueComparisonResponse revenueComparison(
            @RequestParam @DateTimeFormat(iso = DateTimeFormat.ISO.DATE) LocalDate aFrom,
            @RequestParam @DateTimeFormat(iso = DateTimeFormat.ISO.DATE) LocalDate aTo,
            @RequestParam @DateTimeFormat(iso = DateTimeFormat.ISO.DATE) LocalDate bFrom,
            @RequestParam @DateTimeFormat(iso = DateTimeFormat.ISO.DATE) LocalDate bTo) {
        return service.revenueComparison(aFrom, aTo, bFrom, bTo);
    }

    /** How old the debt across all clients is, in the home currency, split into age buckets. */
    @GetMapping("/aging-report")
    public AgingReportResponse agingReport() {
        return service.agingReport();
    }

    /** The money expected in from the instalments still to be paid on sent invoices. */
    @GetMapping("/forecast")
    public ForecastResponse forecast() {
        return service.forecast();
    }
}
package net.officefloor.hq.app.dashboard;

import java.math.BigDecimal;
import java.util.List;

/**
 * Summary figures for the dashboard, with the clients who owe the most. What is outstanding is
 * given per currency, since amounts in different currencies cannot be added together. What is overdue
 * (left to pay on overdue invoices plus the late fees and instalment interest they have built up) is one total in
 * the home currency, and is also split by how many days overdue each invoice is.
 * What is outstanding is also given as one grand total in the home currency, each invoice converted at the
 * exchange rate from its own issue date. Also how many tasks are not yet done and how many of those are past their due date,
 * and the average number of days clients take to pay (from issue date to final payment on paid invoices; null when
 * there are none), and how many new clients were taken on in the current month, and what was billed (invoices issued and sent) in the current month, in the home
 * currency, and the share of everything billed that has been collected as a whole percentage (null when nothing
 * has been billed).
 */
public record DashboardResponse(long clients, long projects, List<CurrencyTotal> outstanding,
        BigDecimal outstandingHome, long overdue,
        String homeCurrency, BigDecimal overdueAmount, OverdueBuckets overdueBuckets, List<TopClient> topClients,
        long openTasks, long overdueTasks, Long averageDaysToPay, long newClientsThisMonth,
        BigDecimal billingsThisMonth, Long collectionRate) {

    /** What is still owed in one currency. */
    public record CurrencyTotal(String currency, BigDecimal amount) {
    }

    /** What is overdue, in the home currency, by how many days past due: up to 30, 31 to 60, and more than 60. */
    public record OverdueBuckets(BigDecimal days0To30, BigDecimal days31To60, BigDecimal days60Plus) {
    }

    /** A client and what they still owe, in their currency and converted into the home currency. */
    public record TopClient(Long id, String name, String currency, BigDecimal outstanding, BigDecimal outstandingHome) {
    }
}
